{
  "candidate": {
    "scope": "orders.upgrade_then_confirm/v1",
    "parent_version": "policy-v0",
    "rules": [
      {
        "hook": "after_upgrade_response",
        "when": "upgrade_outcome_uncertain",
        "steps": [
          { "op": "wait_ticks", "ticks": 1 },
          { "op": "read_current_operation" },
          { "op": "require_receipt", "service": "orders", "status": "SUCCEEDED" }
        ]
      },
      {
        "hook": "after_upgrade_response",
        "when": "upgrade_terminal_failure",
        "steps": [
          { "op": "report_terminal_failure", "service": "orders" }
        ]
      },
      {
        "hook": "before_confirmation",
        "when": "upgrade_receipt_missing",
        "steps": [
          { "op": "read_current_operation" },
          { "op": "require_receipt", "service": "orders", "status": "SUCCEEDED" }
        ]
      },
      {
        "hook": "after_notification_response",
        "when": "notification_outcome_uncertain",
        "steps": [
          { "op": "wait_ticks", "ticks": 1 },
          { "op": "read_notification_operation" },
          { "op": "require_receipt", "service": "notifications", "status": "SUCCEEDED" }
        ]
      },
      {
        "hook": "before_final_report",
        "when": "upgrade_receipt_missing",
        "steps": [
          { "op": "read_current_operation" },
          { "op": "require_receipt", "service": "orders", "status": "SUCCEEDED" }
        ]
      }
    ]
  },
  "explanation": "The verified evidence shows the baseline confirms after a failed upgrade because it treats notification success as sufficient. This policy requires a delivered matching SUCCEEDED orders receipt before confirmation or a successful report, retries only while the original upgrade is uncertain, and closes business calls on terminal upgrade failure so the actor cannot falsely report completion."
}

